comms.text:
@1 דַיָנִין וּפֻרְעָנִין תְּמַנֵי לָךְ בְּכֹל קִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְשִׁבְטָיךְ וִידוּנוּן יָת עַמָא דִין דִקְשׁוֹט:
@2 לָא תַצְלֵי דִין לָא תִשְׁתְּמוֹדַע אַפִּין וְלָא תְקַבֵּל שֹׁחֲדָא אֲרֵי שֹׁחֲדָא מְעַוֵּר עֵינֵי חַכִּימִין וּמְקַלְקַל פִּתְגָמִין תְּרִיצִין:
@3 קֻשְׁטָא קֻשְׁטָא תְּהֵי רָדִיף בְּדִיל דְתֵיחֵי וְתֵירַת יָת אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@4 לָא תִצוֹב לָךְ אֲשֵׁרַת כָּל אִילָן בִּסְטַר מַדְבְּחָא דַיְיָ אֱלָהָךְ דִי תַעְבֶּד לָךְ:
@5 וְלָא תְקִים לָךְ קָמָא דִי סָנֵי יְיָ אֱלָהָךְ:
@6 לָא תִכּוֹס קֳדָם יְיָ אֱלָהָךְ תּוֹר וְאִמָר דִי יְהֵי בֵהּ מוּמָא כֹּל מִדַעַם בִּישׁ אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ הוּא:
@7 אֲרֵי יִשְׁתְּכַח בֵּינָךְ בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ גְבַר אוֹ אִתְּתָא דִי יַעְבֵּד יָת דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְמֶעְבַּר עַל קְיָמֵהּ:
@8 וַאֲזַל וּפְלַח לְטַעֲוַת עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילֵי שְׁמַיָא דִי לָא פַקֵדִית:
@9 וְיִתְחַוֵי לָךְ וְתִשְׁמַע וְתִתְבַּע יָאוּת וְהָא קֻשְׁטָא כֵּוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֶבְתָּא הָדָא בְּיִשְׂרָאֵל:
@10 וְתַפֵּק יָת גַבְרָא הַהוּא אוֹ יָת אִתְּתָא הַהִיא דִי עֲבָדוּ יָת פִּתְגָמָא בִישָׁא הָדֵין לִתְרַע בֵּית דִינָךְ יָת גַבְרָא אוֹ יָת אִתְּתָא וְתִרְגְמִנוּן בְּאַבְנַיָא וִימוּתוּן:
@11 עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטִל דְחַיַב קְטוֹל לָא יִתְקְטֵל עַל מֵימַר סָהִיד חָד:
@12 יְדָא דְסַהֲדַיָא תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְּבַתְרֵיתָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@13 אֲרֵי יִתְכַסֵי מִנָךְ פִּתְגָמָא לְדִינָא בֵּין דְמָא לִדְמָא בֵּין דִינָא לְדִינָא וּבֵין מַכְתַּשׁ סְגִירוּ לְמַכְתַּשׁ סְגִירוּ פִּתְגָמֵי פְלֻגְתָּא דִינָא בְּקִרְוָיךְ וּתְקוּם וְתִסַק לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@14 וְתֵיתֵי לְוָת כָּהֲנַיָא לֵוָאֵי וּלְוָת דַיָנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתִתְבַּע וִיחַוּוּן לָךְ יָת פִּתְגָמָא דְדִינָא:
@15 וְתַעְבֵּד עַל מֵימַר פִּתְגָמָא דִי יְחַוּוּן לָךְ מִן אַתְרָא הַהוּא דִי יִתִּרְעֵי יְיָ וְתִטַר לְמֶעְבַּד כְּכֹל דִי יַלְפֻנָךְ:
@16 עַל מֵימַר אוֹרַיְתָא דִי יַלְפֻנָךְ וְעַל דִינָא דִי יֵימְרוּן לָךְ תַּעְבֵּד לָא תִסְטֵּי מִן פִּתְגָמָא דִי יְחַוּוּן לָךְ יַמִינָא וּשְׂמָאלָא:
@17 וּגְבַר דִי יַעְבֵּד בִּרְשַׁע בְּדִיל דְלָא לְקַבָּלָא מִן כַּהֲנָא דְקָאֵם לְשַׁמָשָׁא תַמָן קֳדָם יְיָ אֱלָהָךְ אוֹ מִן דַיָנָא וְיִתְקְטֵל גַבְרָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@18 וְכָל עַמָא יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יַרְשִׁיעוּן עוֹד:
@19 אֲרֵי תֵעוֹל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וְתֵירְתַהּ וְתֵיתֵב בַּהּ וְתֵימַר אֱמַנִי עֲלַי מַלְכָּא כְּכָל עַמְמַיָא דִי בְסַחֲרָנָי:
@20 מַנָאָה תְמַנֵי עֲלָךְ מַלְכָּא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ מִגוֹ אַחָיךְ תְּמַנֵי עֲלָךְ מַלְכָּא לֵת לָךְ רְשׁוּ לְמַנָאָה עֲלָךְ גְבַר נוּכְרַי דִי לָא אֲחוּךְ הוּא:
@21 לְחוֹד לָא יַסְגֵי לֵהּ סוּסָוָן וְלָא יָתֵב יָת עַמָא לְמִצְרָיִם בְּדִיל לְאַסְגָּאָה לֵהּ סוּסָוָן וַיְיָ אֲמַר לְכוֹן לָא תוֹסְפוּן לְמִתוּב בְּאֹרַח הָדֵין עוֹד:
@22 וְלָא יַסְגֵי לֵהּ נְשִׁין וְלָא יִטְעֵי לִבֵּהּ וְכַסְפָּא וְדַהַבָא לָא יַסגֵי לֵהּ לַחֲדָא:
@23 וִיהֵי:כְמִתְּבֵהּ עַל כָּרְסָא מַלְכוּתֵהּ וְיִכְתּוֹב לֵהּ יָת פַּתְשֶׁגֶן אוֹרַיְתָא הָדָא עַל סִפְרָא מִן קֳדָם כָּהֲנַיָא לֵוָאֵי:
@24 וּתְהֵי עִמֵהּ וִיהֵי קָרֵי בֵהּ כָּל יוֹמֵי חַיוֹהִי בְּדִיל דְיֵלַף לְמִדְחַל קֳדָם יְיָ אֱלָהֵהּ לְמִטַּר יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא וְיָת קְיָמַיָא הָאִלֵין לְמֶעְבָּדְהוֹן:
@25 בְּדִיל דְלָא יְרִים לִבֵּהּ מֵאֲחוֹהִי וּבְדִיל דְלָא יִסְטֵּי מִן תַּפְקֶדְתָּא יַמִינָא וּשְׂמָאלָא בְּדִיל דְיוֹרֵךְ יוֹמִין עַל מַלְכוּתֵהּ הוּא וּבְנוֹהִי בְּגוֹ יִשְׂרָאֵל:
@26 לָא יְהֵי לְכָהֲנַיָא לֵוָאֵי כָּל שִׁבְטָא דְלֵוִי חֳלָק וְאַחֲסָנָא עִם יִשְׂרָאֵל קֻרְבָּנַיָא דַיְיָ וְאַחֲסַנְתֵּהּ יֵיכְלוּן:
@27 וְאַחֲסָנָא לָא יְהֵי לֵהּ בְּגוֹ אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל לֵהּ:
@28 וְדֵין יְהֵי דְחָזֵי לְכָהֲנַיָא מִן עַמָא מִן נָכְסֵי נִכְסָתָא אִם תּוֹר אִם אִמָר וְיִתֵּן לְכַהֲנָא דְרוֹעָא וְלוֹעָא וְקֻבְתָא:
@29 רֵישׁ עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וְרֵישׁ גִזָא דְעָנָךְ תַּפְרֵשׁ לֵהּ:
@30 אֲרֵי בֵהּ יִתִּרְעֵי יְיָ אֱלָהָךְ מִכָּל שִׁבְטָיךְ לְמֵקַם לְשַׁמָשָׁא בִשְׁמָא דַיְיָ הוּא וּבְנוֹהִי כָּל יוֹמַיָא:
@31 וַאֲרֵי יֵיתֵי לֵוָאָה מֵחֲדָא מִקִרְוָיךְ מִכָּל יִשְׂרָאֵל דִי הוּא דָר תַּמָן וְיֵיתֵי בְּכָל רְעוּת נַפְשֵׁהּ לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@32 וִישַׁמַשׁ בִּשְׁמָא דַיְיָ אֱלָהֵהּ כְּכָל אֲחוֹהִי לֵוָאֵי דִמְשַׁמְשִׁין תַּמָן (בִּצְלוֹ) קֳדָם יְיָ:
@33 חֳלָק כָּחֳלָק יֵיכְלוּן בַּר מִמַטַרְתָּא דְיֵיתֵי בְּשַׁבַּתָּא דְכֵן אַתְקִינוּ אֲבָהָתָא:
@34 אֲרֵי אַתְּ עָלֵל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תֵילַף לְמֶעְבַּד כְּתֹעֲבַת עַמְמַיָא הָאִנוּן:
@35 לָא יִשְׁתְּכַח בָּךְ מַעֲבַר בְּרֵהּ וּבְרַתֵּהּ בְּנוּרָא קָסֵם קֻסְמִין מְעָנֵן וּמְנַחֵשׁ וְחָרָשׁ:
@36 וְרָטִין רְטָן וְשָׁאֵל בִּדִין וּדְכוּרוּ וְתָבַע מִן מֵתַיָא:
@37 אֲרֵי מְרָחָק יְיָ כָּל דְיַעְבֵּד אִלֵין וּבְדִיל תּוֹעֲבָתָא הָאִלֵין יְיָ אֱלָהָךְ מְתָרַךְ יָתְהוֹן מִקֳדָמָךְ:
@38 שְׁלִים תְּהֵי בְּדַחַלְתָּא דַיְיָ אֱלָהָךְ:
@39 אֲרֵי עַמְמַיָא הָאִלֵין דִי אַתְּ יָרֵת יָתְהוֹן מִן מְעָנְנַיָא וּמִן קַסָמַיָא שָׁמְעִין וְאַתְּ לָא כֵן יְהַב לָךְ יְיָ אֱלָהָךְ:
@40 נְבִיָא מִבֵּינָךְ מֵאַחָיךְ כְּוָתִי יְקִים לָךְ יְיָ אֱלָהָךְ מִנֵהּ תְּקַבְּלוּן:
@41 כְּכֹל דִי שְׁאֶלְתָּא מִקֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב בְּיוֹמָא דִקְהָלָא לְמֵימָר לָא אוֹסֵף לְמִשְׁמָע יָת קָל מֵימְרָא דַיְיָ אֱלָהַי וְיָת אֶשָׁתָא רַבְּתָא הָדָא לָא אֶחֱזֵי עוֹד וְלָא אֵמוּת:
@42 וַאֲמַר יְיָ לִי אוֹטִיבוּ דִי מַלִילוּ:
@43 נְבִיָא אֲקִים לְהוֹן מִגוֹ אֲחֵיהוֹן כְּוָתָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵהּ וִימַלֵל עִמְהוֹן יָת כָּל דִי אֲפַקְדִנֵהּ:
@44 וִיהֵי גַבְרָא דִי לָא יְקַבֵּל לְפִתְגָמַי דִי יְמַלֵל בִּשְׁמִי מֵימְרִי יִתְבַּע מִנֵהּ:
@45 בְּרַם נְבִיָא דִי יַרְשַׁע לְמַלָלָא פִתְגָמָא בִּשְׁמִי יָת דִי לָא פַקֵדִתֵּה לְמַלָלָא וְדִי יְמַלֵיל בְּשׁוּם טַעֲוַת עַמְמַיָא וְיִתְקְטֵל נְבִיָא הַהוּא:
@46 וַאֲרֵי תֵימַר בְּלִבָּךְ אֶכְדֵן נִדַע יָת פִּתְגָמָא דִי לָא מַלְלֵהּ יְיָ:
@47 דִי יְמַלֵל נְבִיָא בִּשְׁמָא דַיְיָ וְלָא יְהֵי פִתְגָמָא וְלָא יִתְקַיַם הוּא פִתְגָמָא דִי לָא מַלְלֵהּ יְיָ בִּרְשַׁע מַלְלֵהּ נְבִיָא לָא תִדְחַלּ מִנֵהּ:
@48 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעֲהוֹן וְתֵרְתִנוּן וְתֵיתֵב בְּקִרְוֵיהוֹן וּבְבָתֵּיהוֹן:
@49 תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@50 תְּתַקֵן לָךְ אָרְחָא וּתְתַלַת יָת תְּחוּם אַרְעָךְ דִי יַחְסְנִנָךְ יְיָ אֱלָהָךְ וִיהֵי לְמֵעִירוֹק תַּמָן כָּל קָטוֹלָא:
@51 וְדֵין פִּתְגַם קָטוֹלָא דְיֵעִרוֹק תַּמָן וְיִתְקַיַם דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵהּ וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקָמוֹהִי:
@52 וְדִי יֵעוֹל עִם חַבְרֵהּ בְּחֻרְשָׁא לְמִקַץ אָעִין וְתִתְמְרֵיג יְדֵהּ בְּפַרְזְלָא לְמִקַץ אָעָא וְיִשְׁתְּלֵף פַּרְזְלָא מִן אָעָא וְיַשְׁכַּח יָת חַבְרֵהּ וִימוּת הוּא יֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין וְיִתְקַיַם:
@53 דִילְמָא יִרְדוֹף גָאֵל דְמָא בָּתַר קָטוֹלָא אֲרֵי יֵחַם לִבֵּה וְיַדְבְּקִנֵהּ אֲרֵי תִסְגֵי אָרְחָא וְיִקְטְלִנֵהּ נְפַשׁ וְלֵהּ לֵית חוֹבַת דִין דִקְטוֹל אֲרֵי לָא סָנֵי הוּא לֵהּ מִתְּמַלֵי וּמִדְקָמוֹהִי:
@54 עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימָר תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ:
@55 וְאִם יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ וְיִתֶּן לָךְ יָת כָּל אַרְעָא דִי מַלִיל לְמִתַּן לַאֲבָהָתָךְ:
@56 אֲרֵי תִטַר יָת כָּל תַּפְקֶדְתָּא הָדָא לְמֶעְבְּדַהּ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹהִי כָּל יוֹמַיָא וְתוֹסֵף לָךְ עוֹד תְּלַת קִרְוִין עַל תְּלַת אִלֵין:
@57 וְלָא יִשְׁתְּפֵךְ דָם זַכַּי בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וִיהֵי עֲלָךְ חוֹבַת דִין דִקְטוֹל:
@58 וַאֲרֵי יְהֵי גְבַר סָנֵי לְחַבְרֵהּ וְיִכְמַן לֵהּ וִיקוּם עֲלוֹהִי וְיִמְחִנֵהּ נְפָשׁ וִימוּת וְיֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין:
@59 וִישַׁלְחוּן סָבֵי קַרְתֵּהּ וְיִדְבְּרוּן יָתֵהּ מִתַּמָן וְיִתְּנוּן יָתֵהּ בְּיַד גָאֵל דְמָא וִימוּת:
@60 לָא תְחוּס עֵינָךְ עֲלוֹהִי וּתְפַלֵי אַשְׁדִי דָם זַכַּי מִיִשְׂרָאֵל וְיֵיטַב לָךְ:
@61 לָא תַשְׁנֵי תְּחוּמָא דְחַבְרָךְ דִי תְחִימוּ קַדְמָאֵי בְּאַחֲסַנְתָּךְ דִי תַחֲסֵן בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@62 לָא יְקוּם סָהִיד חַד בִּגְבַר לְכָל עַוָיָן וּלְכָל חוֹבִין בְּכָל חֵט דִי יֶחְטֵי עַל מֵימַר תְּרֵין סָהֲדִין אוֹ עַל מֵימַר תְּלָתָא סָהֲדִין יִתְקַיַם פִּתְגָמָא:
@63 אֲרֵי יְקוּם סָהִיד שְׁקַר בִּגְבָר לְאַסְהָדָא בֵהּ סַטְּיָא:
@64 וִיקוּמוּן תְרֵין גֻבְרִין דִי לְהוֹן דִינָא קֳדָם יְיָ קֳדָם כָּהֲנַיָא וְדַיָנַיָא דִי יְהוֹן בְּיוֹמַיָא הָאִנוּן:
@65 וְיִתְבְּעוּן דַיָנַיָא יָאוּת וְהָא סָהִיד שְׁקַר סָהֲדָא שִׁקְרָא אַסְהַד בַּאֲחוֹהִי:
@66 וְתַעְבְּדוּן לֵהּ כְּמָא דִי חַשִׁיב לְמֶעְבַּד לַאֲחוֹהִי וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@67 וּדְיִשְׁתַּאֲרוּן יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד עוֹד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@68 וְלָא תְחוּס עֵינָךְ נַפְשָׁא חֳלַף נַפְשָׁא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא יְדָא חֳלַף יְדָא רַגְלָא חֳלַף רַגְלָא:
@69 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְתֶחֱזֵי סוּסָוָן וּרְתִכִּין עַם סַגִי מִנָךְ לָא תִדְחַל מִנְהוֹן אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ בְּסַעְדָךְ דְאַסְקָךְ מֵאַרְעָא דְמִצְרָיִם:
@70 וִיהֵי כְּמִקְרָבְכוֹן לַאֲגָחָא קְרָבָא וְיִתְקְרִיב כַּהֲנָא וִימַלֵל עִם עַמָא:
@71 וְיֵימַר לְהוֹן שְׁמַע יִשְׂרָאֵל אַתּוּן קְרִיבִין יוֹמָא דֵין לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּעַ לִבְּכוֹן לָא תִדְחֲלוּן וְלָא תִתְבַּהֲתוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן:
@72 אֲרֵי יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן לַאֲגָחָא לְכוֹן קְרָב עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרַק יָתְכוֹן:
@73 וִימַלְלוּן סָרְכַיָא קֳדָם עַמָא לְמֵימָר מָן גַבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא חָנְכֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יַחְנְכִנֵהּ:
@74 וּמָן גַבְרָא דִי נְצִיב כַּרְמָא וְלָא אַחֲלֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יְחַלִנֵהּ:
@75 וּמָן גַבְרָא דִי אֵרַס אִתְּתָא וְלָא נָסְבַהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחֳרָן יִסְבִנַהּ:
@76 וְיוֹסְפוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וְיֵימְרוּן מָן גַבְרָא דְדָחֵל וּתְבִיר לִבָּא יְהַךְ וִיתוּב לְבֵיתֵהּ וְלָא יִתְּבַר יָת לִבָּא דַאַחוֹהִי כְּלִבֵּהּ:
@77 וִיהֵי כַּד יְשֵׁצוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וִימַנוּן רַבָּנֵי חֵילָא בְּרֵישׁ עַמָא:
@78 אֲרֵי תִקְרַב לְקַרְתָּא לַאֲגָחָא (קְרָבָא) עֲלַהּ וְתִקְרֵי לַהּ מִלִין דִשְׁלָם:
@79 וִיהֵי אִם שְׁלַם תַּעֲנִנָךְ וְתִפְתַּח לָךְ וִיהֵי כָּל עַמָא דְיִשְׁתְּכַח בַּהּ יְהוֹן לָךְ מַסְקֵי מִסִין וְיִפְלְחֻנָךְ:
@80 וְאִם לָא תַשְׁלֵם עִמָךְ וְתַעְבֵּד עִמָךְ קְרָב וּתְצוּר עֲלַהּ:
@81 וְיִמְסְרִנַהּ יְיָ אֱלָהָךְ בִּידָךְ וְתִמְחֵי יָת כָּל דְכוּרַהּ לְפִתְגַם דְחָרֶב:
@82 לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכֹל דִי יְהֵי בְקַרְתָּא כָּל עֲדָאַהּ תֵּבוֹז לָךְ וְתֵיכוּל יָת עֲדָאָה דְסַנְאָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@83 כֵּן תַּעְבֵד לְכָל קִרְוַיָא דִי רְחִיקִין מִנָךְ לַחֲדָא דִי לָא מִקִרְוֵי עַמְמַיָא הָאִלֵין אִנוּן:
@84 לְחוֹד מִקִרְוֵי עַמְמַיָא הָאִלֵין דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לָא תְקַיַם כָּל נִשְׁמָתָא:
@85 אֲרֵי גַמָרָא תְגַמְרִנוּן חִתָּאֵי וֶאֱמֹרָאֵי כְּנַעֲנָאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@86 בְּדִיל דִי לָא יַלְפוּן יָתְכוֹן לְמֶעְבַּד כְּכָל תּוֹעֲבָתְהוֹן דִי עֲבָדוּ לְטַעֲוָתְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהֲכוֹן:
@87 אֲרֵי תְצוּר לְקַרְתָּא יוֹמִין סַגִיאִין לַאֲגָחָא עֲלַהּ לְמִכְבְּשַׁהּ לָא תְחַבֵּל יָת אִילָנַהּ לַאֲרָמָא עֲלוֹהִי פַּרְזְלָא אֲרֵי מִנֵה תֵּיכוּל וְיָתֵהּ לָא תְקוּץ אֲרֵי לָא כַאֲנָשָׁא אִילַן חַקְלָא לְמֵיעַל מְקָדָמָךְ בִּצְיָרָא:
@88 לְחוֹד אִילָן דְתִדַע אֲרֵי לָא אִילַן דְמַאֲכָל הוּא יָתֵהּ תְּחַבַּל וּתְקוּץ וְתִבְנֵי כַרְקוֹמִין עַל קַרְתָּא דִי הִיא עָבְדָא עִמָךְ קְרָבָא עַד דְתִכְבְּשַׁהּ:
@89 אֲרֵי יִשְׁתְּכַח קְטִּילָא בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ רָמֵי בְּחַקְלָא לָא אִתְיְדַע מַן קָטְּלֵהּ:
@90 וְיִפְּקוּן סָבָיךְ וְדַיָנָיךְ וְיִמְשְׁחוּן לְקִרְוַיָא דִי סַחֲרָנוּת קְטִילָא:
@91 וּתְהֵי קַרְתָּא דִקְרִיבָא לִקְטִילָא וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא עֶגְלַת תּוֹרֵי דִי לָא אִתְפְּלַח בַּהּ דִי לָא נְגִידַת בְּנוּר:
@92 וְיֶחֱתוּן סָבֵי קַרְתָּא הַהִיא יָת עֲגַלְתָּא לְנַחֲלָא בַיָר דִי לָא יִתְפְּלַח בֵּהּ וְלָא יִזְדְרַע וְיִנְקְפוּן תַּמָן יָת עֲגַלְתָּא בְּנַחֲלָא:
@93 וְיִתְקָרְבוּן כָּהֲנַיָא בְּנֵי לֵוִי אֲרֵי בְהוֹן יִתִּרְעֵי יְיָ אֱלָהָךְ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִּשְׁמָא דַיְיָ וְעַל מֵימְרֵהוֹן יְהֵי כָּל דִין וְכָל מַכְתַּשׁ סְגִירוּ:
@94 וְכֹל סָבֵי קַרְתָּא הַהִיא דִקְרִיבִין לִקְטִילָא יַסְחוּן יָת יְדֵיהוֹן עַל עֲגַלְתָּא דִנְקֶפְתָּא בְנַחֲלָא:
@95 וִיתִיבוּן וְיֵימְרוּן יְדָנָא לָא אַשְׁדוֹ יָת דְמָא הָדֵין וְעֵינָנָא לָא חֲזָאָה:
@96 כָּהֲנַיָא יֵימְרוּן כַּפַּר לְעַמָךְ יִשְׂרָאֵל דִי פְרַקְתָּא יְיָ וְלָא תִתֵּן חוֹבַת דַם זַכַּי בְּגוֹ עַמָךְ יִשְׂרָאֵל וְיִתְכַּפַּר לְהוֹן עַל דְמָא:
@97 וְאַתְּ תְּפַלֵי אַשְׁדִי דַם זַכַּי מִבֵּינָךְ אֲרֵי תַעְבֵּד דְכָשַׁר קֳדָם יְיָ: ססס:

@1 **שפטים ושטרים.** שופטים, דינים הפוסקים את הדין. ושוטרים, הרודין את העם אחר מצותם. שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט: **בכל שעריך.** בכל עיר ועיר: **לשבטיך.** מוסב על תתן לך. שופטים ושוטרים תתן לך לשבטיך בכל שעריך אשר ה' אלהיך נתן לך: **לשבטיך.** מלמד שמושיבין דינין לכל שבט ושבט ובכל עיר ועיר: **ושפטו את העם** וגו' **.** מנה דינין מומחים וצדיקים לשפוט צדק:
@2 **לא תטה משפט.** כמשמעו: **לא תכיר פנים.** אף בשעת הטענות. אזהרה לדין שלא יהא רך לזה וקשה לזה, אחד עומד ואחד יושב. לפי שכשרואה שהדין מכבד את חברו מסתתמין טענותיו: **ולא תקח שחד.** אפלו לשפוט צדק: **כי השחד יעור.** משקבל שחד ממנו אי אפשר שלא יטה את לבו אצלו להפוך בזכותו: **דברי צדיקים.** דברים המצדקים, משפטי אמת:
@3 **צדק צדק תרדף.** הלך אחר בית דין יפה: **למען תחיה וירשת.** כדאי הוא מנוי הדינין הכשרים להחיות את ישראל ולהושיבן על אדמתן:
@4 **לא תטע לך אשרה.** לחייבו עליה משעת נטיעתה ואפלו לא עבדה עובר בלא תעשה על נטיעתה: **לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך.** אזהרה לנוטע אילן ולבונה בית בהר הבית:
@5 **ולא תקים לך מצבה.** מצבת אבן אחת, להקריב עליה אפלו לשמים: **אשר שנא.** מזבח אבנים ומזבח אדמה צוה לעשות, ואת זו שנא כי חק היתה לכנענים. ואף על פי שהיתה אהובה לו בימי האבות, עכשיו שנאה, מאחר שעשאוה אלו חק לעבודה זרה:
@6 **לא תזבח** וגו' **כל דבר רע.** אזהרה למפגל בקדשים על ידי דבור רע. ועוד נדרשו בו שאר דרשות בשחיטת קדשים:
@7 **לעבר בריתו.** אשר כרת אתכם שלא לעבוד עבודה זרה:
@8 **אשר לא צויתי.** לעבדם:
@9 **נכון.** מכון העדות:
@10 **והוצאת את האיש ההוא:. אל שעריך** וגו' **.** המתרגם אל שעריך, לתרע בית דינך, טועה, שכן שנינו אל שעריך זה שער שעבד בו, או אינו אלא שער שנדון בו, נאמר שעריך למטה ונאמר שעריך למעלה (פסוק ב) מה שעריך האמור למעלה שער שעבד בו אף שעריך האמור למטה שער שעבד בו. ותרגומו לקרוך:
@11 **שנים [עדים] או שלשה.** אם מתקימת עדות בשנים למה פרט לך בשלשה, להקיש שלשה לשנים, מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כלם:
@13 **כי יפלא.** כל הפלאה לשון הבדלה ופרישה, שהדבר נבדל ומכסה ממך: **בין דם לדם.** בין דם טמא לדם טהור: **בין דין לדין.** בין דין זכאי לדין חיב: **בין נגע לנגע.** בין נגע טמא לנגע טהור: **דברי ריבת.** שיהו חכמי העיר חולקים בדבר, זה מטמא וזה מטהר זה מחיב וזה מזכה: **וקמת ועלית.** מלמד שבית המקדש גבוה מכל המקומות:
@14 **הכהנים הלוים.** הכהנים שיצאו משבט לוי: **ואל השפט אשר יהיה בימים ההם.** ואפלו אינו כשאר שופטים שהיו לפניו אתה צריך לשמוע לו. אין לך אלא שופט שבימיך:
@16 **ימין ושמאל.** אפלו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין, וכל שכן שאומר לך על ימין ימין ועל שמאל שמאל:
@18 **וכל העם ישמעו.** מכאן שממתינין לו עד הרגל וממיתין אותו ברגל:
@21 **לא ירבה לו סוסים.** אלא כדי מרכבתו, שלא ישיב את העם מצרימה, שהסוסים באים משם. כמה שנאמר בשלמה, ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה (מלכים א' י, כט) :
@22 **ולא ירבה לו נשים.** אלא שמונה עשרה, שמצינו שהיו לו לדוד שש נשים, ונאמר לו ואם מעט ואספה לך כהנה וכהנה (שמואל ב' יב, ח) : **וכסף וזהב לא ירבה לו מאד.** אלא כדי לתן לאכסניא [לאפסניא] :
@23 **והיה כשבתו.** אם עשה כן, כדאי הוא שתתקיים מלכותו: **את משנה התורה.** שתי ספרי תורה. אחת שהיא מנחת בבית גנזיו ואחת שנכנסת ויוצאת עמו. ואונקלוס תרגם פתשגן, פתר משנה לשון שנון ודבור:
@24 **דברי התורה.** כמשמעו:
@25 **ולבלתי סור מן המצוה.** אפלו מצוה קלה של נביא: **למען יאריך ימים.** מכלל הן אתה שומע לאו. וכן מצינו בשאול שאמר לו שמואל שבעת ימים תוחל עד בואי אליך להעלות עלות (שמואל א' י, ח) וכתיב ויוחל שבעת ימים (שמואל א' יג, ח) ולא שמר הבטחתו לשמור כל היום, ולא הספיק להעלות העולה עד שבא שמואל ואמר לו נסכלת לא שמרת וגו' ועתה ממלכתך לא תקום (שם יג ז. יד) . הא למדת, שבשביל מצוה קלה של נביא נענש: **הוא ובניו.** מגיד שאם בנו הגון למלכות הוא קודם לכל אדם:
@27 **כל שבט לוי.** בין תמימין בין בעלי מומין: **חלק.** בבזה: **ונחלה.** בארץ: **אשי ה'.** קדשי המקדש [הקדשים] : **ונחלתו.** אלו קדשי הגבול תרומות ומעשרות. אבל נחלה גמורה לא יהיה לו בקרב אחיו. ובספרי דרשו, ונחלה לא יהיה לו. זו נחלת שאר: **בקרב אחיו.** זו נחלת חמשה. ואיני יודע מה היא. ונראה לי שארץ כנען שמעבר הירדן ואלך נקראת ארץ חמשה עממין, ושל סיחון ועוג, שני עממין אמורי וכנעני. ונחלת שאר לרבות קיני וקנזי וקדמוני. וכן דורש בפרשת מתנות שנאמרו לאהרן על כן לא היה ללוי וגו' (דברים י, ט) להזהיר על קיני וקנזי וקדמוני. שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי ונחלה לא יהיה לו אלו נחלת חמשה. בקרב אחיו אלו נחלת שבעה. נחלת חמשה שבטים ונחלת שבעה שבטים. ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד, שכן משה הנחיל לראובן וגד וחצי שבט מנשה, ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה, ושבעה האחרים נטלו מאליהן אחרי מות יהושע, מתוך כך הזכיר חמשה לבד ושבעה לבד: **כאשר דבר לו.** לאהרן, בארצם לא תנחל וגו' אני חלקך (במדבר יח, כ) :
@28 **מאת העם.** ולא מאת הכהנים: **אם שור אם שה.** פרט לחיה: **הזרוע.** מן הפרק של ארכבה עד כף של יד שקורין אשפלדו''ן [עצם השכם] : **והלחיים.** עם הלשון. דורשי רשומות היו אומרים, זרוע, תחת יד, שנאמר (במדבר כה, ז) ויקח רמח בידו. לחיים, תחת תפלה, שנאמר (תהל' קו, ל) ויעמד פינחס ויפלל: **והקבה.** תחת (במד' כה) האשה אל קבתה:
@29 **ראשית דגנך.** זו תרומה, ולא פרש בה שעור, אבל רבותינו נתנו בה שעור, עין יפה אחד מארבעים, עין רעה אחד מששים, בינונית אחד מחמשים. וסמכו על המקרא שלא לפחות מאחד מששים, שנאמר וששיתם האיפה מחמר השערים (יחזקאל מה, יג) ששית האיפה, חצי סאה. כשאתה נותן חצי סאה לכור, הרי אחד מששים, שהכור שלשים סאין: **וראשית גז צאנך.** כשאתה גוזז צאנך בכל שנה תן ממנה ראשית לכהן. ולא פרש בה שעור. ורבותינו נתנו בה שעור אחד מששים. וכמה צאן חיבות בראשית הגז, חמש רחלות, שנאמר (שמואל א' כה, יח) וחמש צאן עשויות. רבי עקיבא אומר ראשית גז שתים, גז צאנך ארבע, תתן לו הרי חמש:
@30 **לעמד לשרת.** מכאן שאין שרות אלא מעומד:
@32 **וכי יבא הלוי.** יכול בבן לוי ודאי הכתוב מדבר, תלמוד לומר ושרת, יצאו לויים שאין ראויין לשרות: **ובא בכל אות נפשו** וגו' **ושרת.** למד על הכהן שבא ומקריב קרבנות נדבתו או חובתו ואפלו במשמר שאינו שלו. דבר אחר עוד למד על הכהנים הבאים לרגל שמקריבין במשמר ועובדין בקרבנות הבאים מחמת הרגל, כגון מוספי הרגל, ואף על פי שאין המשמר שלהם:
@33 **חלק כחלק יאכלו.** מלמד שחולקין בעורות ובבשר שעירי חטאות. יכול אף בדברים הבאים שלא מחמת הרגל, כגון תמידין ומוספי שבת ונדרים ונדבות, תלמוד לומר לבד ממכריו על האבות, חוץ ממה שמכרו האבות בימי דוד ושמואל, שנקבעו המשמרות ומכרו זה לזה טול אתה שבתך ואני אטול שבתי:
@34 **לא תלמד לעשות.** אבל אתה למד להבין ולהורות, כלומר להבין מעשיהם כמה הם מקלקלים, ולהורות לבניך לא תעשה כך וכך, שזה הוא חק הגוים:
@35 **מעביר בנו ובתו באש.** היא עבודת המולך. עושה מדורות אש מכאן ומכאן ומעבירו בין שתיהם: **קסם קסמים.** איזהו קוסם, האוחז את מקלו ואומר אם אלך אם לא אלך. וכן הוא אומר, (הושע ד, יב) עמי בעצו ישאל ומקלו יגיד לו: **מעונן.** רבי עקיבא אומר אלו נותני עונות, שאומרים עונה פלונית יפה להתחיל. וחכמים אומרים אלו אוחזי העינים: **מנחש.** פתו נפלה מפיו, צבי הפסיקו בדרך, מקלו נפל מידו:
@36 **וחבר חבר.** שמצרף נחשים או עקרבים או שאר חיות למקום אחד: **ושאל אוב.** זה מכשפות ששמו פיתום ומדבר משחיו ומעלה את המת בבית השחי שלו: **וידעני.** מכניס עצם חיה ששמה ידוע, לתוך פיו, ומדבר העצם על ידי מכשפות: **ודרש אל המתים.** כגון המעלה בזכרותו והנשאל בגלגלת:
@37 **כל עשה אלה.** עשה כל אלה לא נאמר אלא כל עשה אלה, אפלו אחת מהן:
@38 **תמים תהיה עם ה' אלהיך.** התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות, אלא כל מה שיבא עליך קבל בתמימות ואז תהיה עמו ולחלקו:
@39 **לא כן נתן לך ה' אלהיך.** לשמוע אל מעוננים ואל קוסמים שהרי השרה שכינה על הנביאים ואורים ותמים:
@40 **מקרבך מאחיך כמני.** כמו שאני מקרבך מאחיך יקים לך תחתי, וכן מנביא לנביא:
@45 **אשר לא צויתיו לדבר.** אבל צויתיו לחברו: **ואשר ידבר בשם אלהים אחרים.** אפלו כון את ההלכה, לאסור את האסור ולהתיר את המתר: **ומת.** בחנק. שלשה מיתתן בידי אדם, המתנבא מה שלא שמע ומה שלא נאמר לו ונאמר לחברו, והמתנבא בשם עבודה זרה. אבל הכובש את נבואתו והעובר על דברי נביא והעובר על דברי עצמו מיתתן בידי שמים, שנאמר אנכי אדרש מעמו (פסוק יט) :
@46 **וכי תאמר בלבבך.** עתידין אתם לומר, כשיבא חנניה בן עזור ומתנבא (ירמיה כז, טז) הנה כלי בית ה' מושבים מבבלה עתה מהרה, וירמיהו עומד וצווח על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה, (שם כז, כב) בבלה יובאו עם גלות צדקיהו:
@47 **אשר ידבר הנביא.** ויאמר דבר זה עתיד לבא עליכם, ותראו שלא יבא, הוא הדבר אשר לא דברו ה' והרג אותו. ואם תאמר זו במתנבא על העתידות, הרי שבא ואמר עשו כך וכך ומפי הקדוש ברוך הוא אני אומר, כבר נצטוו שאם בא להדיחך מאחת מכל המצות לא תשמע לו, אלא אם כן ממחה הוא לך שהוא צדיק גמור, כגון אליהו בהר הכרמל שהקריב בבמה בשעת אסור הבמות כדי לגדור את ישראל. הכל לפי צורך השעה וסיג הפרצה, לכך נאמר אליו תשמעון: **לא תגור ממנו.** לא תמנע עצמך מללמד עליו חובה ולא תירא לענש עליו:
@50 **תכין לך הדרך.** מקלט מקלט היה כתוב על פרשת דרכים: **ושלשת את גבול ארצך.** שיהא מתחלת הגבול עד העיר הראשונה של עיר מקלט, כשעור מהלך שיש ממנה עד השניה. וכן משניה, לשלישית. וכן מן השלישית, עד הגבול השני של ארץ ישראל:
@52 **ונדחה ידו.** כשבא להפיל הגרזן על העץ, ותרגומו ותתמריג ידיה, לשון ונשמטה ידו להפיל מכת הגרזן על העץ. כי שמטו הבקר, תרגם יונתן (שמואל ב' ו, ו) ארי מרגוהי תוריא: **ונשל הברזל מן העץ.** יש מרבותינו אומרים נשמט הברזל מקתו, ויש מהם אומרים שישיל הברזל חתיכה מן העץ המתבקע, והיא נתזה והרגה:
@53 **פן ירדף גאל הדם.** לכך אני אומר להכין לך דרך, וערי מקלט רבים:
@55 **ואם ירחיב.** כאשר נשבע לתת לך ארץ קיני וקנזי וקדמוני:
@56 **ויספת לך עוד שלש.** הרי תשע. שלש שבעבר הירדן ושלש שבארץ כנען ושלש לעתיד לבא:
@58 **וכי יהיה איש שנא לרעהו.** על ידי שנאתו הוא בא לידי וארב לו. מכאן אמרו עבר אדם על מצוה קלה סופו לעבור על מצוה חמורה. לפי שעבר על לא תשנא, סופו לבא לידי שפיכת דמים. לכך נאמר כי יהיה איש שנא לרעהו וגו' , שהיה לו לכתוב וכי יקום איש וארב לרעהו והכהו נפש:
@60 **לא תחוס עינך.** שלא תאמר הראשון כבר נהרג, למה אנו הורגים את זה ונמצאו שני ישראלים הרוגים:
@61 **לא תסיג גבול.** לשון (ישעיה מב, יז) נסגו אחור, שמחזיר סימן חלקת הקרקע לאחור לתוך שדה חברו למען הרחיב את שלו. והלא כבר נאמר (ויקרא יט, יג) לא תגזל, מה תלמוד לומר לא תסיג, למד על העוקר תחום חברו שעובר בשני לאוין. יכול אף בחוצה לארץ, תלמוד לומר בנחלתך אשר תנחל וגו' , בארץ ישראל עובר בשני לאוין, בחוצה לארץ אינו עובר אלא משום לא תגזל:
@62 **עד אחד.** זה בנה אב. כל עד שבתורה שנים, אלא אם כן פרט לך בו אחד: **לכל עון ולכל חטאת.** להיות חברו נענש על עדותו, לא עונש גוף ולא עונש ממון, אבל קם הוא לשבועה. אמר לחברו תן לי מנה שהלויתיך, אמר לו אין לך בידי כלום, ועד אחד מעיד שיש לו, חיב להשבע לו: **על פי שני עדים.** ולא שיכתבו עדותם באגרת וישלחו לבית דין, ולא שיעמוד תרגמן בין העדים ובין הדינים:
@63 **לענות בו סרה.** דבר שאינו, שהוסר העד הזה מכל העדות הזאת, כגון, שאמרו להם והלא עמנו הייתם אותו היום במקום פלוני:
@64 **ועמדו שני האנשים.** בעדים הכתוב מדבר, ולמד שאין עדות בנשים, ולמד שצריכין להעיד עדותן מעומד: **אשר להם הריב.** אלו בעלי הדין: **לפני ה'.** יהי דומה להם כאלו עומדין לפני המקום, שנאמר (תהלים פב, א) בקרב אלהים ישפט: **אשר יהיו בימים ההם.** יפתח בדורו כשמואל בדורו, צריך אתה לנהוג בו כבוד:
@65 **ודרשו השופטים היטב.** על פי המזימין אותם, שבודקים וחוקרים את הבאים להזימם בדרישה ובחקירה: **והנה עד שקר.** כל מקום שנאמר עד, בשנים הכתוב מדבר:
@66 **כאשר זמם.** ולא כאשר עשה. מכאן אמרו, הרגו אין נהרגין: **לעשות לאחיו.** מה תלמוד לומר לאחיו, למד על זוממי בת כהן נשואה שאינן בשריפה, אלא כמיתת הבועל שהוא בחנק, שנאמר (ויקרא כא, ט) היא באש תשרף, היא ולא בועלה. לכך נאמר כאן לאחיו, כאשר זמם לעשות לאחיו, ולא כאשר זמם לעשות לאחותו. אבל בכל שאר מיתות השוה הכתוב אשה לאיש, וזוממי אשה נהרגין כזוממי איש. כגון שהעידוה שהרגה את הנפש, שחללה את השבת, נהרגין במיתתה. שלא מעט כאן אחותו אלא במקום שיש לקים בהן הזמה במיתת הבועל:
@67 **ישמעו ויראו.** מכאן שצריכין הכרזה, איש פלוני ופלוני נהרגין על שהוזמו בבית דין:
@68 **עין בעין.** ממון, וכן שן בשן וגו' :
@69 **כי תצא למלחמה.** סמך הכתוב יציאת מלחמה לכאן, לומר לך, שאין מחסר אבר יוצא למלחמה. דבר אחר לומר לך, אם עשית משפט צדק אתה מבטח שאם תצא למלחמה אתה נוצח. וכן דוד הוא אומר (תהלים קיט, קכא) עשיתי משפט וצדק בל תניחני לעשקי: **על איבך.** יהיו בעיניך כאויבים, אל תרחם עליהם כי לא ירחמו עליך: **סוס ורכב.** בעיני כלם כסוס אחד, וכן הוא אומר (שופטים ו, טז) והכית את מדין כאיש אחד. וכן הוא אומר (שמות טו, יט) כי בא סוס פרעה: **עם רב ממך.** בעיניך הוא רב, אבל בעיני אינו רב:
@70 **כקרבכם אל המלחמה.** סמוך לצאתכם מן הספר מגבול ארצכם: **ונגש הכהן.** המשוח לכך. והוא הנקרא משוח מלחמה: **ודבר אל העם.** בלשון הקדש:
@71 **שמע ישראל.** אפלו אין בכם זכות אלא קרית שמע בלבד, כדאי אתם שיושיע אתכם: **על איביכם.** אין אלו אחיכם, שאם תפלו בידם אינם מרחמים עליכם, אין זו כמלחמת יהודה עם ישראל, שנאמר (דה''י ב' כח, טו) ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה, וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל, ויביאום ירחו עיר התמרים אצל אחיהם, וישובו שמרון, אלא על אויביכם אתם הולכים, לפיכך התחזקו למלחמה: **אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו.** ארבע אזהרות כנגד ארבעה דברים שמלכי האמות עושים. מגיפים בתריסיהם כדי להקישן זה לזה כדי להשמיע קול שיחפזו אלו שכנגדם וינוסו, ורומסים בסוסיהם ומצהילין אותם להשמיע קול שעטת פרסות סוסיהם, וצווחין בקולם ותוקעין בשופרות ומיני משמיעי קול: **אל ירך לבבכם.** מצהלת סוסים: **אל תיראו.** מהגפת התריסין: **ואל תחפזו.** מקול הקרנות: **ואל תערצו.** מקול הצוחה:
@72 **כי ה' אלהיכם** וגו' **.** הם באים בנצחונו של בשר ודם ואתם באים בנצחונו של מקום. פלשתים באו בנצחונו של גלית, מה היה סופו, נפל ונפלו עמו: **ההלך עמכם.** זה מחנה הארון:
@73 **ולא חנכו.** לא דר בו. חנוך לשון התחלה: **ואיש אחר יחנכנו.** ודבר של עגמת נפש הוא זה:
@74 **ולא חללו.** לא פדאו בשנה הרביעית, שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכל הדמים בירושלים:
@75 **פן ימות במלחמה.** ישוב פן ימות, שאם לא ישמע לדברי הכהן כדאי הוא שימות:
@76 **ויספו השטרים.** למה נאמר כאן ויספו, מוסיפין זה על דברי הכהן, שהכהן מדבר ומשמיע מן (פסוק ג, ד) שמע ישראל עד להושיע אתכם, ומי האיש ושני ושלישי כהן מדבר ושוטר משמיע, וזה שוטר מדבר ושוטר משמיע: **הירא ורך הלבב.** רבי עקיבא אומר כמשמעו, שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה. רבי יוסי הגלילי אומר הירא מעבירות שבידו, ולכך תלתה לו תורה לחזור על בית וכרם ואשה לכסות על החוזרים בשביל עברות שבידם, שלא יבינו שהם בעלי עברה, והרואהו חוזר אומר שמא בנה בית או נטע כרם או ארש אשה:
@77 **שרי צבאות.** שמעמידין זקפין, מלפניהם ומלאחריהם וכשילין של ברזל בידיהם וכל מי שרוצה לחזור הרשות בידו לקפח את שוקיו. זקפין, בני אדם עומדים בקצה המערכה לזקוף את הנופלים ולחזקם בדברים שובו אל המלחמה ולא תנוסו, שתחלת נפילה ניסה:
@78 **כי תקרב אל עיר.** במלחמת הרשות הכתוב מדבר, כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחקת וגו' :
@79 **כל העם הנמצא בה.** אפלו אתה מוצא בה משבעה אמות שנצטוית להחרימם, אתה רשאי לקימם: **למס ועבדוך.** עד שיקבלו עליהם מסים ושעבוד:
@80 **ואם לא תשלים עמך ועשתה עמך מלחמה.** הכתוב מבשרך שאם לא תשלים עמך סופה להלחם בך אם תניחנה ותלך: **וצרת עליה.** אף להרעיבה ולהצמיאה ולהמיתה מיתת תחלואים:
@81 **ונתנה ה' אלהיך בידך.** אם עשית כל האמור בענין, סוף שה' נותנה בידך:
@82 **והטף.** אף טף של זכרים. ומה אני מקים (פסוק יג) והכית את כל זכורה, בגדולים:
@85 **כאשר צוך.** לרבות את הגרגשי:
@86 **למען אשר לא ילמדו.** הא אם עשו תשובה ומתגירים, אתה רשאי לקבלם:
@87 **ימים.** שנים: **רבים.** שלשה. מכאן אמרו אין צרין על עירות של נכרים פחות משלשה ימים קודם לשבת. ולמד שפותח בשלום שנים או שלשה ימים. וכן הוא אומר (שמואל ב' א, א) וישב דוד בצקלג ימים שנים, ובמלחמת הרשות הכתוב מדבר: **כי האדם עץ השדה.** הרי כי משמש בלשון דלמא. שמא האדם עץ השדה להכנס בתוך המצור מפניך להתיסר ביסורי רעב וצמא כאנשי העיר, למה תשחיתנו:
@88 **עד רדתה.** לשון רדוי, שתהא כפופה לך:
@90 **ויצאו זקניך.** מיחדים שבזקניך, אלו סנהדרי גדולה: **ומדדו.** ממקום שהחלל שוכב: **אל הערים אשר סביבת החלל.** לכל צד לידע איזו קרובה:
@92 **אל נחל איתן.** קשה, שלא נעבד: **וערפו.** קוצץ ערפה בקופיץ. אמר הקדוש ברוך הוא תבא עגלה בת שנתה שלא עשתה פרות ותערף במקום שאינו עושה פרות, לכפר על הריגתו של זה שלא הניחוהו לעשות פרות:
@95 **ידינו לא שפכה.** וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה. והכהנים אומרים כפר לעמך ישראל:
@96 **ונכפר להם הדם.** הכתוב מבשרם שמשעשו כן, יכפר להם העון:
@97 **ואתה תבער.** מגיד שאם נמצא ההורג אחר שנתערפה העגלה הרי זה יהרג, והוא הישר בעיני ה':

@1 **שופטים וגו'**. סמך מצוה זו למצות ג' פעמים וגו' שלפניה, להעיר שהגם שמצוך לעלות שלשה פעמים בשנה ליראות את פני ה' ושם היא עומדת סנהדרי גדולה קבועה אף על פי כן צריך למנות שופטים וכו' ולא יסמכו על בית דין שלפני ה' בלשכת הגזית לבד, והטעם כדי שלא תענה הדין עד עלות אל המקום, וטעם השוטרים אמרו בפסיקתא ר' אלעזר בן שמוע אומר אם יש שוטרים יש שופטים אם אין שוטרים אין שופטים ע''כ, הדברים מוכיחים שאם אין שוטרים אין חיוב מצות שופטים, ומעתה כל שיודעים ישראל שהעם אינם נשמעים לשופטים והשופטים אינם יכולים לכופם אין חיוב במינוי השופטים, וכל שהעם נשמעים לדייניהם בלא שוטרים חייבין למנות שופטים וקוראים אנו בשופט זה שופט ושוטר:
@1 **תתן לך**. פירוש שהממנים עצמן לא יאמרו בדעתן שלא תשלוט עליהם מקל מרדותו של שופט ושוטר כיון שהם הממנים אותו אלא שימנום לשפוט ולרדות אותם, והוא אומרו **תתן לך** פירוש עליך:
@1 **בכל שעריך**. טעם אומרו **בכל**, שצריך למנות בכל עיר ועיר ובכל פלך ופלך בארץ ישראל, ובברייתא (ילקוט) אמרו וז''ל בכל שעריך בא הכתוב להקיש סנהדרי קטנה לסנהדרי גדולה מה גדולה דנה והורגת אף קטנה דגה והורגת ע''כ, ונראה שדרשתם היא מתיבת בכל שכלל הכתוב כל הסנהדרין יחד לומר ששוים בכח אחד:
@1 **ואומרו אשר ה' אלהיך** נותן לך אמרו ז''ל (מכות ז'.) שבא לומר שאין חיוב האמור בענין אלא בארץ אשר ה' אלהיך נותן לך ולא בחוץ לארץ:
@1 **ואומרו לשבטיך** רבותינו ז''ל (ספרי) פרשוהו שמוסב למעלה, וקשה למה לא כתבו במקומו על זה הדרך תתן לך לשבטיך בכל שעריך אשר וגו', ואולי שנתכוון להסמיכה למאמר ושפטו את העם משפט צדק להעיר כי הוא זה טעם שמצוה לתת שופטים בכל עיר, ובעיר שיש ב' שבטים ב' שופטים כדי שישפטו משפט צדק, ודקדק לומר **את העם** פירוש שלא יהיה הפרש ביניהם ויהיו נדונים זה את זה בהשואה כיון שכל שבט נידון לפני בית דינו, ובזה אנו מרוויחים ישוב מאמר **ושפטו** שאם בא להזהיר לדיינים היה לו לדבר נוכח כסדר שדיבר בסמוך לא תטה לא תכיר וגו', ורש''י ז''ל פירוש שהוא אזהרה לממנים למנות צדיקים, ולדבריו היה לו לומר על זה הדרך שופטים ששופטים בצדק וגו' תתן לך וגו' ולדרכנו יבא על נכון:
@1 **וראיתי** לרמב''ם ז''ל (הל' סנהדרין פ''א) שהשמיט דין זה שצריך לכל שבט ושבט ולא כתב אלא שלכל עיר ועיר, ואולי שסובר הרמב''ם שכוונת רבותינו ז''ל שדרשו לשבטיך שצריך בית דין לכל שבט הוא קודם שדרשו שצריך בכל עיר, אבל אחר שצריך לכל עיר אין עוד צורך למנות לכל שבט, וזה לשון הברייתא בסנהדרין (דף ט''ז ע''ב) תנו רבנן מנין שמעמידין שופטים לישראל תלמוד לומר שופטים תתן וגו' לכל שבט ושבט מנין תלמוד לומר שופטים לשבטיך, לכל עיר ועיר מנין תלמוד לומר שופטים לשעריך ע''כ, וקשה למה דרש התנא תיבת לשבטיך שהוא בסוף פסוק קודם תיבת בכל שעריך שקדומה לה שמן הראוי היה לתנא להקדים דרשת בכל שעריך, אלא הרי זה מגיד שלא בא חיוב לשבטיך אלא קודם חיוב כל שעריך אבל אחר שצוה בכל שעריך אין מקום להצריך לשבטים, ולזה הרמב''ם שכתב חיוב בכל עיר אין מקום לומר בכל שבט, ולדרך זה דרשת התנא הוא על זה הדרך שמחייבך הכתוב לתת שופטים לכל שבט בין יהיה בעשרה עיירות בין יהיה בעיר אחת, וחזר ואמר שאם יהיה בהרבה עיירות יתן לכל עיר ועיר:
@1 **ואם** תאמר אם יתן בכל עיר למה הוצרך לומר לשבטיך, משום שזולת לשבטיך לא הייתי מפרש בכל שעריך בכל עיר ועיר שהייתי אומר שרוצה לומר שעריך של כללות ישראל בין שבארץ ישראל בין שבעבר הירדן לא של כל עיר ועיר שבארץ, ואחר אומרו לשבטיך שפירושו הוא לכל שבט נתחייבנו לומר בכל שעריך בכל עיר, ולזה כשפסק הרמב''ם בכל עיר אין מקום לומר לשבטיך שאז תפרש בדבריו כדברי התום' שם בסנהדרין שאם יש בעיר ב' שבטים צריך ב' בתי דינים:
@1 **משפט צדק**. ולא אמר בצדק כאומרו (ויקרא י''ט ט''ו) בצדק תשפוט עמיתך, כאן העיר הערה גדולה לחפץ לשפוט בצדק, והוא כי כשירצה לעמוד הדיין על משפט האנשים אשר להם הריב יהיה בסדר זה שיעביר מבין עיניו ב' הנושאים ולא ילביש משא ומתן ההלכות שיעשה באנשים אשר להם הריב לומר כפי זה יתחייב פלוני וכפי זה יהיה להיפך אלא יעשה עיונו וצדדי ההלכה כאלו אין אדם שצריך להוראה זו עתה אלא לעמוד על הדין לדעת הלכות התורה, ואחר שיעמוד עליו בדרך זה מה שיעלה במצודתו ידין בו לבעלי דינים יזכה הזכאי ויתחייב החייב, והוא אומרו **ושפטו את העם משפט** פירוש כבר הוא משפט בפני עצמו זה יהיה צדק, אבל זולת זה כשיעריך בדעתו בעת שמזקק ומצרף הדין לבעלי דינים על כל פנים יהיה א' יותר מתקרבת דעתו אליו ולא יצא המשפט צדק, ובפרט במשפטים שתלוים בשיקול הדעת ובהטיה מועטת בנקל יטה דעתו:
@1 **ובדרך** רמז ירמוז על דרך אומרו (תהלים צ''ו) ישפוט תבל בצדק, ואמרו אנשי אמת (זוהר ח''ג קצ''ח) כי ב''ד עליון יקרא צדק, ואמרו ז''ל (ביצה ט''ז.) כי בראש השנה מזונותיו של אדם קבועים וכו', והנה כשיפול ההפרש על הממון בין אדם לחבירו ועמדו לפני השופט אם ישפוט על פי התורה אשר צוה ה' כשיזכו הראוי לזכות וגו' הנה הם שופטים המשפט עצמו ששפט ב''ד עליון הנקרא צדק, והוא אומרו **ושפטו את העם משפט צדק** פירוש ששפט בית דין העליון שנקרא צדק:
@2 **לא תטה משפט וגו'**. לא יחד האזהרה לשופטים וצוה לנוכח, להעיר כי כללות ישראל ישנם גם כן באלו אזהרות אם לא ימנו השופטים כדרך שנצטוו, הם המטים משפט הם העוברים על כל האמור:
@3 **צדק צדק תרדוף וגו'**. בא להזהיר כשיש בעיר ב' אנשים מופלגים בחכמה ושנים אחרים גם כן חכמים אלא שאינם בסוג הראשון אל יאמר אדם כיון ששני אנשים יכולין להורות ולשפוט בצדק לא אטריח את המופלגים לישא בעול מינוי הדיינות, או לצד שצריך להם טורח במינוים ימנע ויסתפק בקטנים, תלמוד לומר צדק צדק פירוש הגם שהשגת לדיינים שהם ראויים, עליך לחזור אחר היותר ראוים מהם:
@4 **לא תטע לך אשרה וגו'**. רבותינו ז''ל אמרו (סנהדרין ז':) כל המעמיד דיין שאינו הגון כאלו נוטע אשרה ע''כ, ולדבריהם אמר תיבת לך לומר שאינו מעלה עליו כאלו וכו' אלא אם כשיעמידנו תהיה כוונתו לאיזו סיבה שנוגעת ממנה, אבל זולת זה אם טעה בדיין שאינו הגון וחשב שהוא הגון והעמידו אינו נחשב עליו כהעמדת אשרה:
@6 **לא תזבח וגו' אשר יהיה בו מום**. ולא אמר אשר בו מום, כפי מה שדרשו ז''ל (ספרי) שבא הכתוב לאסור מום עובר, רמזו בתיבת **יהיה** לומר כל הוית מום בין קבוע בין עובר. ואפשר עוד לומר שאם הוחלט בה אבר שנעשה בו בעלת מום ואמרו הרופאים שעל כל פנים צריך לחותכו הגם שעדיין לא חתכו הרי זה פסולה, והוא אומרו **לא תזבח** וגו' **אשר יהיה בו מום** פירוש הגם שעתה אינו מום כיון שעומד להיות מום לא תזבחנו:
@7 **כי ימצא בקרבך**. אומרו **בקרבך**, לחייב על הדבר לבני המקום ששם ימצא האיש עושה הרע ואחריהם יתחייבו כל יושבי הארץ, והוא מה שגמר אומר **באחד שעריך**, ורבותינו ז''ל (כתובות מ''ה:) דרשו שעריך לגזירה שוה שער שנמצאו בו ולא שער שנידונו בו, ואמרו **אשר ה' אלהיך נותן לך**, נתכוין לומר שעל מנת כן ה' נתנה לך:
@7 **לעבור בריתו**. פירוש צריך שידע שהוא עובר ברית ה', ולזה צריך שיתרו בו ויודיעוהו מה גדלו מעשיו הרעים, גם רמז שאם אמר למתרים שהוא נשבע לעבוד עבודה זרה שיודיעוהו שקדמה לו ברית על זה ואין שבועתו חלה לבטל הראשונה והרי הוא עובר ברית ה' ויהרג:
@11 **יומת המת**. כפל לומר המת, להעיר כי אם לא נמצאו לו עדים והתראה בן מות הוא לשמים אלא שבעדים והתראה יומת בידי אדם המת שהיה עומד למיתה בידי שמים:
@13 **כי יפלא וגו' למשפט**. הוצרך לומר למשפט, להעיר שלא נאמרו דינים אלו אלא במורה שהוא ראוי להורות משפט, וכן אמרו במשנה (סנהדרין פ''ו:) תלמיד שאינו ראוי להוראה פטור, אלא שראיתי בברייתא (שם פ''ז.) שדרשו פיטור תלמיד שאינו ראוי להוראה מאומרו כי יפלא במופלא שבב''ד, וכתבו רש''י ותוס' בהנחנקין שפירושו מופלא מומחה ולמעוטי תלמיד, והרמב''ם פירש בי''ד (הלכות ממרים פ''ג ה''ה) שהכוונה הוא מי שלא יפלא ממנו אלא דבר מופלא, ומעתה לפי זה אומרו **למשפט** לומר שאין הדין האמור בזקן זה אלא בהוראה למעשה, וכמו שאמרו במשנה שם וז''ל אינו חייב עד שיורה לעשות שנאמר והאיש אשר יעשה בזדון ע''כ, והנה מפסוק זה אין הוכחה אלא על מעשהו על פי הוראתו ולא אם הורה לאחרים לעשות, ולמדין לה מאומרו למשפט שאם הורה לאחרים חייב:
@13 **או** ירצה על זה הדרך **כי יפלא** וגו' **למשפט** הגם שהיה הלכה למעשה והורה לעשות הפך כוונת החולקים ונמצא הדין לא כן הוא אף על פי שהורה בדבר שחייב על זדונו כרת וכו' לא יומת פירוש הגם שהורה לעשות הפך הרבים החולקים עליו לא יומת עד שיורה לעשות הפך אשר יגידו עליו בית דין הגדול שבלשכת הגזית, וכן מוכיחים הדברים בסנהדרין:
@14 **ודרשת והגידו לך**. פירוש עליך אתה לדרוש שיאמרו לך טעם הדין, והם גם כן חייבים להגיד לך טעם דבריהם, אבל אם לא דרש אין חיוב עליהם להגיד לו:
@15 **ועשית על פי הדבר**. פירוש לא מבעיא המשפט עצמו שהגידו לך אלא אפילו משפטים אחרים הנבנים על פי שמועה זו, כי כמה משפטים יסתעפו מפרט משפט אחד:
@19 **כי תבא וגו' ואמרת וגו' שום תשים וגו'**. מאומרו **כי תבא** וגו' **ואמרת** משמע כי לא מצות ה' עליהם למלוך מלך אלא אם יאמרו הרשות בידם, וממה שגמר אומר **שום תשים** שיעור הלשון מוכיח שמצות ה' היא להמליך עליהם מלך:
@19 **ונראה** שכוונת הכתובים היא על זה הדרך לפי שיש במינוי המלך ב' גדרים, א' שיהיה המבטח בו להנהיג המלחמות בעוצם חכמתו ולצאת כגבור ביום קרב כסדר מלכי האומות, וזה הוא דבר שנאוי בעיני ה' כי סדר מלכי האומות לא ילכו בהם אחרי כשרון המעשה אלא אחרי תועליות החושיות הגם שלא ימצא בו דבר טוב מהמושכל, גם ישימו בו כסלם ותקותם ומן ה' יסור לבבם, וגדר ב' הוא לכבוד ולתפארת ישראל וכדי שה' יעשה בזכותו כדרך שהיה ה' מושיע ישראל ביד השופטים וביד מלכי ישראל הכשרים, וצא ולמד מדוד המלך וכו', ודבר זה הוא חן ושכל טוב בעיני אלהים ואדם:
@19 **ולזה** בא דברו הטוב כאן ואמר **כי תבא** וגו' **ואמרת אשימה עלי מלך ככל הגוים** וגו' וזה גדר הראשון שזכרנו, וגמר אומר **שום תשים** וגו' פירוש לא יקום הדבר הרע הזה, אלא המשימות שתשים הוא על זה הדרך אשר יבחר ה' אלהיך בו, ואמרו רבותינו ז''ל (בתוספתא סנהדרין פ''ג) וז''ל אין מעמידין מלך בתחילה אלא על פי ב''ד של ע' זקנים ועל פי נביא וכו' ע''כ, ומלך המתמנה בסדר זה אינו כסדר מלך המתמנה על הגוים כמו שבא בדבריהם ככל הגוים. וכפי זה מאמר **שום תשים** היא מצוה ושלילת גדר שכנגד תנאיה, ולזה נתחכם ה' להקדים מאמר **ואמרת אשימה** וגו' להעירך את אשר יכוין אליו לשלול אותו במאמר שום תשים וגו', שזולת זה לא הייתי מבין שאוסר לשום מלך ככל הגוים, והגם שיאמרו אשר יבחר אין מובן שבא לאסור ככל הגוים ויהיה זה וזה, ולא חש להבין במאמר שום תשים שהוא רשות מכפל שום תשים:
@19 **ותמצא** שה' הקפיד על ישראל כששאלו בימי שמואל לתת להם מלך (ש''א ח'), והענין קשה למה יקפיד ה' עליהם והלא לו יהיה שכונת ה' בפסוק זה לרשות ולא למצוה סוף סוף הרשות נתונה, וכפי מה שכתבנו יש מקום לה' להקפיד על הדבר כיון שצוה ה' עליהם לבל יאמרו לשום מלך ככל הגוים כמו שפירשנו ושאלו המלך ואמרו (ש''א ח' ה') לשפטינו ככל הגוים לזה הקפיד ה', אבל אם היו שואלים להם מלך כרצונו יתברך לא לכח ולגבורה כדרך הגוים היו מקיימין מצות עשה:
@19 **וראיתי** בסנהדרין פרק כהן גדול (כ':) שנחלקו רבותינו ז''ל וז''ל רבי יהודה אומר ג' מצות נצטוו ישראל בכניסתן לארץ להעמיד להם מלך ולהכרית זרעו של עמלק ולבנות בית הבחירה רבי נהוראי אומר לא נאמרה פרשה זו אלא כנגד תרעומתן שנאמר ואמרת אשימה עלי מלך וגו' ע''כ, ודברינו עולין לדברי ר' יהודה ולא לדברי ר' נהוראי, והגם שהלכה כרבי יהודה וכן פסק רמב''ם בפ''א מהלכות מלכים אף על פי כן צריך ליישב הכתוב לסברת רבי נהוראי שפשט אומרו שום תשים יגיד שמצות ה' לשום מלך:
@19 **ואפשר** לומר כי אם ישראל יהיו כשרים ולא ישאלו מלך והיה ה' למלך עליהם כדרך אומרו (ש''א י''ב) וה' אלהיכם מלככם, גם ה' יחפוץ להיות מלך ישראל הוא לבדו, אבל אם ישראל יכנסו בגדר שאלה שחפצים במלך עליהם אז מצות המלך עליהם לעשותו כאומרו שום תשים, ולזה לא אמר הכתוב **שום תשים** אלא אחר מאמר **ואמרת אשימה** וגו', וכפי זה אפילו אליבא דרבי נהוראי יפרש **שום תשים** מצוה אחר שיאמרו אשימה וגו':
@25 **לבלתי רום לבבו**. פירוש על דרך אומרם ז''ל (אבות פ''ו מ''א) ומלבשתו ענוה ויראה, והוא אומרו כי באמצעות קריאת התורה לא ירום לבבו וגו', וכנגד היראה אמר לפני זה למען ילמד ליראה:
@26 **לא יהיה לכהנים וגו' ונחלה לא יהיה וגו'**. כפל הכתוב הענין לומר שהגם שעברו ונתנו להם נחלה אותה נחלה לא תקום לזכותם, והוא אומרו **ונחלה לא יהיה** וגו'. וטעם סמיכות מצוה זו למצות המלך, לומר שהמלך שוה לעם במצות האמורים בענין לתת להם מתנותיהם ולא ירום לבבו מאחיו לבלתי סור מן המצוה שמצוה ה' לכללות ישראל:
@38 **תמים תהיה עם ה'**. פירוש לפי שצוה עליו בסמוך לבל יעונן ויכשף ולבל ישאל באוב וגו' אמר **תמים** וגו', פירוש כלומר טעם כל הדברים הוא לדעת העתידות ולהתנהג על אשר יורו ולתקן החסרון כאשר יוכל עשות, אם תהיה עם ה' תמים תהיה לא יחסר לך דבר ואין מה שיגיד המזל עליך תתקיים לרעה, וזה לך האות אברהם שהתהלך לפני ה' הגם שהראה המזל עליו שלא יוליד נתהפך וילד (שבת קנ''ו:), וכפי זה תיבת **תהיה** נמשכת למעלה ולמטה על זה הדרך תמים תהיה אם תהיה עם ה', או על זה הדרך תמים תהיה כשאתה עם אלהיך:
@39 **כי הגוים וגו' ישמעו**. פירוש יש להם לשמוע ולקבל את אשר יגידו להם המעוננים כי יודיעום המעוננים מה שרשום במזל, **ואתה לא כן** פירוש לא תהא הודעת העתידות לך כן אלא נביא אקים וגו':
@39 **או** ירמוז על זה הדדך **לא כן** וגו', פירוש אינך במצב זה כמותם אלא נתנם לך ה' אלהיך תחת ממשלתך כל המזלות וכל צבא השמים כאומרו (תהלים ח') כל שתה תחת רגליו, וכמו שדרשו ז''ל (שבת קנ''ו:) בפסוק צדק יקראהו לרגלו, ואומרו **נביא אקים** וגו' בא להשיב סוף כל סוף כפי זה יהיו הגוים בהדרגה גדולה שידעו העתידות מה שאין כן ישראל, לזה אמר נביא אקים וגו', ואולי שכן הבין שאול כששאל בבעלת אוב (ש''א כ''ח), כי לא אסר ה' לשאול אוב או ידעוני אלא במקום שיקים נביא אבל זולת זה אם יצטרכו לדעת שאול ישאלו בהם:
@41 **ככל אשר שאלת וגו'**. אולי שבא לומר שהם גרמו לעצמם שאין כולם נביאים כמו שאמרו ביום הקהל קרב אתה ושמע ופחדו מצער הנסבב מהנבואה לזה גם ה' יתן להם נביא והצריך לדבר אליו יבא ויגידנו, ולטעם זה אמר הכתוב כל האמור בענין:
@41 (כ כב) **אך הנביא אשר יזיד וגו'**. צריך לדעת א' אומרו **אך**, גם אומרו **אשר יזיד** ולא הספיק לומר אשר ידבר וגו', ב' אומרו **וכי תאמר בלבבך** וגו' **אשר ידבר** וגו' **ולא יהיה הדבר** וגו' פשיטא שאם לא יהיה מה שצוה שלא דבר ה' הדבר ההוא, ג' אומרו **אשר ידבר בשם ה'** למה בפסוק שלפניו אמר בשמי ובפסוק זה אמר בשם ה', ד' אומרו **הוא הדבר** שלא היה לו לומר אלא לא דברו ה' ואני יודע שחוזר להדבר ההוא:
@41 **אכן** יתבאר הענין על פי מה שאמר הנביא במעשה יהושפט ואחאב במלחמת רמות גלעד (מ''א כ''ב) שכל הנביאים פה אחד דברו לאחאב עלה והצלח, ומדברי מיכיהו בן ימלה נתגלה הדברים שרוח יצא מלפני ה' לפתות אחאב לעלות וליפול במלחמה, ובחידושי על דברי נביאים דקדקתי למה בתחלה עבר על מיכיהו רוח נבות ונתנבא כנביאים הראשונים ואמר עלה והצלח ואח''כ בנבואה אחרונה דבר נבואת ה' ולא הועיל לפניו רוח נבות, ועל הרוח גם כן תמיה אני איך לא קיים שליחותו אשר יצא לעשות, עוד קשה למיכיהו למה בטל עצת ה' ח''ו ומחשבותיו שחשב להפיל אחאב במלחמת רמות גלעד והוא בא וגילה סודו לאחאב עצמו:
@41 **אכן** הן הנה הדברים אשר העיר ה' בנועם דבריו, לפי שהכל גלוי וצפוי לפני הבורא כי יבא זמן שתצא רוח מלפניו ותטעה הנביאים והגם ששקר דברו עם כל זה אנוסים הם, לזה כשבא לצוות עונש הנביא הקדים ואמר **אך הנביא** אך מיעט נביא כיוצא בזה שידבר דבר ולא יקום ולא ימות, ודקדק לומר **אשר יזיד** להעירך שלא ימות אלא נביא אשר יזיד לדבר וגו' לומר אבל נביא שדבר שקר ולא הזיד וכגון שהטעהו רוח נבות שזה אין עליו אשמת דבר כי הרוח בהסכמת ה' יצא והמתנבאים מצדו נקיים הם מהעון. והגם שבסנהדרין (פ''ט.) אמרו שצדקיהו בן כנענה חייב הגם שרוח נבות הטעתו, הוא מטעם שאמרו שם דהוה ליה למידן אין ב' נביאים מתנבאים בסגנון אחד אבל זולת זה פטור היה, והגם שד' מאות נביאים אמרו כן וגם מיכיהו בן ימלה גם כן אמר עלה והצלח וגומר, עם כל זה כולם פתחו פיהם להתנבאות והרוח דברה בפיהם וכשהרגישו שנבאו בסגנון א' לא הוסיפו לדבר עוד בדבר הזה מה שאין כן צדקיהו, ועל זה יאמר אשר יזיד וגו' ומת וגו':
@41 **ומעתה** כאן הבן שואל במה נדע הדבר וגו', ואם ממה שלא יהיה הדבר חיישינן לרוח נבות המטעה וכיוצא בה ולמה יומת האיש הנביא כיון שהרוח שיצא בדבר ה' הטעתו, וכיוצא בדבר אם במעשה רמות לא היה בא מיכיהו וגילה הסוד היו מתחייבים מיתה כל ד' מאות נביאים על לא חמס עשו וה' אוהב משפט, והוא אומרו **וכי תאמר** וגו' **איכה נדע הדבר אשר לא דברו ה'**, כאן כלל דבר ה' לנביא וכלל גם כן דבר ה' לרוח צא ועשה כן:
@41 **ואמר אשר ידבר הנביא** וגו' פירוש אם הנביא יאמר נבואתו בשם ה' והוא מה שדקדק לומר בשם ה', **ולא יהיה הדבר** וגו' אז תדע כי בזדון דברו הנביא פירוש ולא בא דברו מצד רוח שהטעתו, והטעם כי לא ינוח רוח שקר בשם ה' הנכבד כי ה' אלהים אמת, והוא אומרו **הוא הדבר אשר לא דברו ה'** פירוש הוא שאני אומר לך עליו שלא דברו ה', וגם לא בא ברוח אלא בזדון, והוא אומרו **בזדון דברו** הנביא, אבל יש דבר אחר שהגם שהוא שקר ואין התורה יכולה לומר לך לא דברו ה' בזדון דברו הנביא והוא כשלא ידבר הנביא בשם ה' שהגם שיהיה שקר יש לחוש לרוח כרוח נבות:
@41 **ובזה** יערב לנפש אדם ענין מיכיהו כי בתחלה לא הזכיר שם ה' ולזה לא היה אומר אלא דברי הרוח עד שנתחכם יהושפט ואמר אליו (דה''ב י''ח ט''ו) אני משביעך אשר לא תדבר אלי רק אמת בשם ה', פירוש נתחכם לומר לו התנאי שהתנה ה' כאן ואמר אשר ידבר הנביא בשם ה' לפי מה שפירשנו שידבר בשם ה', ובזה אם יש רוח מטעה תפנה מקום, וכן היה כשהזכיר אליו שם ה' ואמר הנביא בשם ה' ברח לו נבות ואמר הנביא האמת במה שהוא:
@41 **ובזה** נתיישבו כל הדקדוקים שדקדקנו בענין נבואת רמות גלעד והגם שלא מצינו שהזכיר מיכיהו שם ה', הזכירו ומקרא קצר הוא כיון שהזכירו יהושפט וכוון מיכיהו לשם שהזכיר יהושפט הועיל, ולא תקשה מאומרו שם כמה פעמים אני משביעך וגו' בשם ה' שיראה שהשביעו כמה פעמים לדבר בשם ה', כי אולי שלא הרגיש מיכיהו בדקדוק זה של יהושפט אלא בפעם אחרונה:
@41 **או** אפשר כי מאמר בשם ה' אינו נסמך למאמר אני משביעך אלא מאמר בפני עצמו שחדש באחרונה, ולפי זה לא קשה למה גילה מיכיהו סוד ה', כי יחרב העולם ולא ישתנה מקור האמת לייחד שמן על דבר שקר ח''ו, ומה גם כי על כל פנים עשה הרוח פעולתו כי לא האמין אליו אחאב ועלה ונפל ונמצאת מחשבת ה' קיימת ולא מתייחס השקר לשם ה' אלהים אמת:
@55 **ואם ירחיב וגו' לאבותיך**. פירוש עצמן כי הם ינחלו הארץ לעתיד לבא, ואמר זה יושג להם אם ישמרו את כל התורה ויעשוה ותהיה השמירה והעשיה מאהבת ה' ולא מיראה הדור ההוא אשר יעמוד בזה, בימיו יקים ה' דברו הטוב לתת כל העשרה עממין ויעמיד ביד ישראל כל הטוב שהבטיח לעשות לאבות ביום עומדם בתחיה, ורבותינו ז''ל (סנהדרין צ''ט:) העירו שגאולה העתידה תלויה בעבודת ה' מאהבה דוקא:
@58 **וכי יהיה איש שונא וגו'**. פרשה זו רומזת מה שאמרו בגמ' מכות דף י''ב שלשה טעיות עתיד שרו של אדום לטעות לעתיד לבא, ואחד מהם הוא שערי מקלט קולטות ההורג בשוגג והוא מזיד, וידוע כי שרו של אדום הוא ס''מ הוא שטן (ב''ב ט''ז.) הוא יצר הרע ועליו העיד הכתוב כאן, ואמר **כי יהיה איש שונא** כי אין שונא לאדם כיצרו הרע והוא מקור השנאה, **לרעהו** כי הוא מראה ריעות לכל כי לטובתם מיעצם, והוא שונא לו ומבקש רעתו בדרך אהבה וריעות, **וארב** שאורב לו להחטיאו כי יש לך לדעת שעבירה ראשונה שעושה האדם אינו עושה אלא כשגגה ובזה מוצא שער הצר ליכנס לנפש, גם מקדים להאדם כאומרו (בראשית ד') לפתח חטאת רובץ קודם בא המנגדו באדם, גם מסביר לו פנים על מעשה הרע ויאמר לרע טוב ואין לך אורב גדול מזה, ובזה מתגבר עליו, והוא אומרו **וקם עליו** מה שאין כן קודם לכן שהיה כחוט השערה הלך בתוך האדם (סוכה נ''ב:) ועל ידי החטא יתגבר ויקום עליו:
@58 **ואומר והכהו נפש** כאן העיר שהוא מדבר על ס''מ ולזה אמר והכהו נפש פירוש שחובל בנפשו כי על ידי החטא תמות הנפש, **ונס אל אחת** פירוש אם ינום אל אחת הערים האל לבצר עצמה שהיא מערי המקלט, **ושלחו זקני עירו** הם בית דין של מעלה שהיא עיר של השר של אדום, **ולקחו אותו** ועל פי המשפט יתנוהו ביד גואל הדם הוא אבינו שבשמים:
@58 **ואומרו ומת** כאן רמז סוד אומרם ז''ל (סנהדרין לח:) מושיט אצבעו בהם ושרפם, והוא אומרו **ביד גואל הדם ומת** פירוש בנגיעת יד ה' בו בזה הוא מת מעצמו, ולפי שאמרו ז''ל כי הריגת ס''מ תהיה גם כן על ידי ישראל שידם תהיה בו להמיתו עם ה' ברוך הוא, לזה אמר **לא תחוס עליו**, והגם שהצדיקים הרויחו באמצעותו, יש להם להביט אל דם נקי כמה דמים רבים ששפך באורבו, ואז **וטוב לך** תהיה נחלטת בחינת הטוב לך, כי בהבטל רוח הטומאה תהיה נשלמת בחינת הטוב במקומה שהם בני ישראל:
@66 **ועשיתם לו כאשר זמם**. רבותינו ז''ל אמרו (מכות ה':) מכאן הרגו אין נהרגים כאשר זמם ולא כאשר עשה, וקשה דלמא אמר הכתוב כאשר זמם להתחייב אפילו לא עשה אלא מעת אשר ענה סרה וזמם לעשות רעה לאחיו נתחייב, וכשנעשה מעשה על ידו ונהרג יש כאן זמם ועשה וקורא אני בו גם כן זמם ונוסף שעשה ואין כאן טענת אין עונשין מן הדין:
@66 **אכן** עיקר הדרשה היא ממה שהיה לו לומר כאשר ענה על אחיו וחוזר למה שאמר שקר ענה באחיו יעשו לו כאשר ענה, ובמאמר זה ישנו לחיוב בין נהרג בין לא נהרג שניהם נכללים במשמעות אשר ענה, ומה שלא אמר לשון הכולל והלך לבקש לשון זה אשר זמם לדיוק בא, לומר דוקא זמם ולא עשה כדבריהם ז''ל, וז''ל בברייתא אמרו אמר לו אביו לאו ק''ו הוא אמר לו למדתנו רבינו אין עונשין מן הדין וכו', אין להקשות מזה לדבריהם, כי בלא טעם אין עונשין מן הדין היה הק''ו מכריח לומר שלא בא הכתוב לפוטרן אם הרגו שהרי ק''ו הדברים ואין כח בדיוק לדחות הק''ו, ולאוקמי קרא שלא בדיוק, אם לא מטעם שדחה רבי אין עונשין מן הדין:
@69 **כי תצא למלחמה וגו'**. אולי שרמז הכתוב מלחמת האדם עם יצרו, ובא להסיר מלבבו מורך, ואמר **כי תצא למלחמה** הידועה שאין גדולה ממנה, והנה במלחמה זו יש ב' דברים קשים לאדם שמתישים כוחו, א' הוא שאינו מלומד במלחמה כמו שהוא מלומד ורגיל במין מלחמה זו יצרו הרע, ב' שהרכבת האדם חוכקת דברי היצר בכל אשר יאמר אליו בעניני האיסור לגנוב ולגזול ולגאות ולאכול כל אשר תאוה נפשו, וזה ימנעהו מלשמוע אל דברי התורה והמצות, ומה גם אחר שנכשל בעבירות רבות שיתוספו כוחות הרע שנולדו ממעשיו הרעים כמו שפירשתי במקומות אחרים והרי הוא ביניהם כחררה שאין לה הופכין:
@69 **לזה** בא דבר ה' כאן ואמר **כי תצא למלחמה** וראית בעיני שכלך **סוס ורכב**, סוס כנגד מה שהוא היצר סוס מוכן למלחמה מה שאינו כן האדם, רכב כנגד הרכבת האדם שנוטה וחושקת לדברים, ואומרו **עם רב ממך** כנגד כוחות הרע שניתוספו ממנו מצד מעשיו הרעים כמו שאמרנו, אף על פי כן בא דברו הטוב ואמר **לא תירא מהם**, והטעם הוא **כי ה' אלהיך עמך** פירוש הן אמת אם היית בא למלחמה בכחך אין בך כח לעמוד במלחמה זו אבל כיון שה' אלהיך עמך כחו גדול להצילך, כי כשבא אדם ליטהר ימינו יתברך מקבלתו ונדבק לה' והוא יכניע מציריו:
@69 **וגמר** אומר **המעלך מארץ מצרים** כי זה מופת חותך כי ה' מפרק הקליפה מן הקדושה ומבררה, והוא סוד העלאת ישראל ממצרים כידוע ליודעי חן, וזה לך האות כדי שתתחזק במלחמה, וכן הוא אומר (תהלים ל''ז) צופה רשע לצדיק וגו' ה' לא יעזבנו בידו, ואמרו ז''ל (קידושין ל':) שהכתוב מדבר על יצר הרע שהוא מתגבר על האדם וה' עוזרו ומצילו מידו:
@69 **להלחם וגו' להושיע וגו'**. פירוש להלחם וגו' לאבד אויביכם, ואומרו **להושיע** וגו' פירוש שלא ימות מבני ישראל אחד במלחמה, וזה הוא עיקר הנס שתהיה המלחמה כבדה באויביהם ולא יפקד אחד מבני ישראל, ואולי כי לזה נתכוון במה שאמר בתחילת הכתוב ה' **אלהיכם** הזכיר הרחמים והדין, רחמים להושיע ישראל, דין לאבד אויביהם, וזולת זה היה די באומרו כי אלהיכם הולך:
@76 **מי האיש הירא וגו'**. רבותינו ז''ל אמרו (סוטה מ''ד.) זה הירא מעבירות שבידו, פירוש על דרך אומרו (ישעי' ל''ג) פחדו בציון חטאים, שכל מי שיש בידו עבירות לבו ירא וחרד מעצמו, ואפילו אינו יודע שיש בידו עבירות הפחד הנכנם בלבבו במלחמה תודיעהו כי יש בידו עבירות, ורבותינו ז''ל (או''ח סי' נ''ר בשם הירושלמי) שיערו העון שיכנס בלבו הפחד מיוצרו שאפילו אין בידו אלא שדיבר בין ישתבח ליוצר, והטעם כי הנכנם למלחמה צריך לעשות לו נם להנצל מחרב אויב וכל שבידו מבחינת הרע אינו ראוי לנס ומזלו יפחידו:
@78 (י~טו) **כי תקרב וגו'**. אולי פרשה זו תרמוז על פי מה שאמר הרשב''י בספר הזוהר (ח''ב ס''ב.) כי האדון ב''ה שולח נשמה יתירה להאדם מעולם העליון להדריכו בדרך ישר ובאמצעותה ימלט האדם מהמחטיאו, וצוה ה' לנשמה ואמר **כי תקרב אל עיר** זה הוא גוף האדם שנקרא עיר כאומרם בספר הזוהר (ז''ח רות צ''ז) בפסוק עיר קטנה וז''ל עיר קטנה דא גופא דבר נש ע''כ, למלחמה כי צריך כח להציל האדם מיד מרשיעו:
@78 **ודקדק** לומר עליה פירוש בשביל העיר למלטה מיצר הרע על דרך אומרו (קהלת ט') ובא אליה וגו' ומלט העיר בחכמתו (נדרים ל''ב:), **וקראת אליה לשלום** פירוש שלא תבא אליה בפסיעותיך להטותו לדרך הטוב מן הקצה אל הקצה, אלא בתחילה בקרבך תקרא אליה לשלום שעשה יעשה גם לעולם העליון ויהנה בזה ובבא ויתן חלק לגופניות וחלק לרוחניות כי גם לעולם העליון צריך האדם למזונות ואם לא יטריח בעולם הזה בעד עולם הבא גם כן, נמצא שלא יגיעו ויאבד לעולם ועד ודרך זה יקרא דברי שלום שהוא הביצוע:
@78 **ואומרו והיה אם שלום**. פירוש והיה לשון שמחה היא אם שלום תענך, ואמר **ופתחה** פירוש אין צורך אלא פתיחה לבד ואם יפתח כפתחו של מחט הקב''ה יפתח לו כפתחו של אולם, והוא מה שגמר אומר **והיה כל העם הנמצא בה** רמ''ח איברים ושס''ה גידים הכל ישתעבד לנשמה, בין בבחינת מצות עשה יהיו למם לעשות בגופם ובממונם וכו', בין בבחינת מצות לא תעשה **ועבדוך** פירוש כעבד הירא מרבו לבל נטות מדבריו ימין ושמאל:
@78 **ואומרו ואם לא תשלים וגו'**. פירוש אם לא השלימה העיר ונטתה אשוריה מני דרך, ולפעמים יקר מקרה שאחר שהתחיל האדם להטיב מעשיו ישוב אחורנית, וכשאירע זה להאדם יגדיל רשע ויתחזק יצרו עליו יותר מבראשונה להלחם עם הנשמה, והוא אומרו **ועשתה עמך מלחמה** יצו ה' לצור על העיר בסיגופים וכמאמרם ז''ל (ברכות ה'.) לעולם ירגיז אדם יצר טוב על יצר הרע והרגזתו הוא לסגף עצמו בדברים המותרים לו, גם בתעניות ומלקיות ובכי להתיש כח הרע שבעיר, ומבטיחו ה' ליתנה בידו כאומרו ונתנה ה' אלהיך בידך, **והכית כל זכורה** הוא כח ס''מ וחיילותיו:
@78 **ואומרו לפי חרב** על דרך אומרו (תהלים קמ''ט) רוממות אל בגרונם וחרב פיפיות בידם:
@78 **ואומרו רק הנשים והטף** פירוש נשים הם נפש ורוח ונקראו נשים בערך הנשמה כידוע ליודעי חן, והטף הם מצות ומעשים טובים שעשה אדם קודם שהיה מתועב בעיני ה' בסוד (תהלים נ') ולרשע אמר אלהים מה לך לספר חקי, וכשאדם חוזר בו יחשבו לזכות:
@78 **גם** על פי דבריהם ז''ל שאמרו (יומא פ''ו:) שגגות נעשות לו כזכיות ולהם יקרא טף:
@78 **ואומרו והבהמה** הוא תאות החומר שיקרא בהמה, **וכל אשר בעיר תבוז לך** שהכל יהיה לתועלת הנשמה לתקן הצריך לתקן להשגת המושכלות, כי גם תאות הבהמי תסגל סגל הטוב במה שנוגע לה:
@78 **ואומרו כן תעשה לכל הערים וגו'**. פירוש כל מצות האמורות בענין אינם אלא לעדים שהם הגופות שנתרחקו, על דרך אומרו (ישעי' נ''ז) לרחוק ולקרוב, שבעל עבירות יקרא רחוק מהשכינה שהיא מקור הקדושה שממנה היא מחצב הנשמה העליונה, אבל עיר שהיא מערי הגוים פירוש שאין לה קשר עם הקדושה ויצאתה ממקורה ברוב פשעיה ככל הגוים אין לנשמה חלק עמה ולא תקוה בה להשיבה, והוא אומרו **אשר לא מערי הגוים** וגו', כי בחינות ההם אין להם אלא להחרימם, וזו היתה שגגת משה בקבלת ערב רב (שמו''ר פמ''ב), וה' אמר אליו ששורשם רע ואינם עומדים בגדר הקדושה ומובדלים לחלק רע, וכשהיה מחיה אותם פירוש לקרבם לקודש אינו מחיה בם כל נשמה, דקדק לומר כל היא הרוח שזוכה ראשונה עם הנשמה:
@78 **חסלת פרשת שופטים**
